//! Cross-platform Ecliptic Remote Desktop client orchestration.

mod abr;
mod audio;
mod clipboard;
mod input;
mod media;
mod pairing;
mod session;

pub use abr::*;
pub use audio::*;
pub use clipboard::*;
pub use input::*;
pub use media::*;
pub use pairing::*;
pub use session::*;

use std::{
    io,
    net::{SocketAddr, ToSocketAddrs, UdpSocket},
    path::PathBuf,
    sync::{mpsc, Arc, Mutex},
    thread,
    time::{Duration, SystemTime, UNIX_EPOCH},
};

use erd_net::{
    DatagramCipher, DatagramError, Direction, PskIdentity, TlsPskClient, TlsPskError, TlsPskStream,
};
use erd_proto::{
    AudioFragment, BitrateAdjust, Capabilities, ClipboardSyncDirection, ClipboardSyncOrigin,
    ClipboardSyncUpdate, ControlMessage, CursorUpdate, FrameChunk, FrameHeader, Handshake,
    InputEvent, PacketHeader, PacketType, PairingGrant, PairingReject, PairingRejectReason,
    PairingRequest, WireCodec, PROTOCOL_VERSION,
};
use rand::{rngs::OsRng, RngCore};
use thiserror::Error;

use crate::{
    AssembledFrame, AudioFragmentReassembler, CursorState, FrameAssembler, PairingRecord,
    PairingStore, PairingStoreError, PlatformClipboard,
};

pub const DEFAULT_TCP_PORT: u16 = 19_730;
pub const DEFAULT_UDP_PORT: u16 = 19_731;
pub const CONNECT_TIMEOUT: Duration = Duration::from_secs(10);
pub const HEARTBEAT_INTERVAL: Duration = Duration::from_secs(2);
pub const HANDSHAKE_ACK_TIMEOUT: Duration = Duration::from_secs(10);
const TCP_RUNTIME_READ_SLICE: Duration = Duration::from_millis(5);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SessionState {
    Disconnected,
    Connecting,
    AwaitingPairing,
    AwaitingHandshakeAck,
    Ready,
}

#[derive(Debug, Clone)]
pub struct SessionConfig {
    pub host: String,
    pub tcp_port: u16,
    pub udp_port: u16,
    pub client_name: String,
    pub capabilities: Capabilities,
    pub pairing_store_path: Option<PathBuf>,
    pub connect_timeout: Duration,
    pub handshake_ack_timeout: Duration,
}

impl SessionConfig {
    pub fn direct(host: impl Into<String>, client_name: impl Into<String>) -> Self {
        Self {
            host: host.into(),
            tcp_port: DEFAULT_TCP_PORT,
            udp_port: DEFAULT_UDP_PORT,
            client_name: client_name.into(),
            capabilities: Capabilities::STREAM_CONFIGURATION | Capabilities::TEXT_CLIPBOARD_SYNC,
            pairing_store_path: None,
            connect_timeout: CONNECT_TIMEOUT,
            handshake_ack_timeout: HANDSHAKE_ACK_TIMEOUT,
        }
    }
}

#[derive(Debug, Clone)]
pub struct ReadySession {
    pub pairing: PairingRecord,
    pub server: Handshake,
    pub session_salt: [u8; 16],
}

#[derive(Debug, Clone, PartialEq)]
pub enum SessionEvent {
    Frame(AssembledFrame),
    Audio(Vec<u8>),
    Cursor(CursorState),
    Clipboard(String),
    Ping,
    Ignored,
}

#[derive(Debug, Error)]
pub enum SessionError {
    #[error("session is not ready")]
    NotReady,
    #[error("pairing rejected: {0:?}")]
    PairingRejected(PairingRejectReason),
    #[error("pairing record {0} was not found")]
    PairingNotFound(String),
    #[error("expected {expected:?}, received {actual:?}")]
    UnexpectedPacket {
        expected: PacketType,
        actual: PacketType,
    },
    #[error("handshake acknowledgement timed out")]
    HandshakeAckTimeout,
    #[error("session lock was poisoned")]
    Poisoned,
    #[error("address resolution returned no endpoints")]
    NoAddress,
    #[error("TCP runtime stopped")]
    TcpRuntimeStopped,
    #[error("protocol error: {0}")]
    Protocol(#[from] erd_proto::CodecError),
    #[error("TLS transport error: {0}")]
    Tls(#[from] TlsPskError),
    #[error("UDP transport error: {0}")]
    Datagram(#[from] DatagramError),
    #[error("pairing store error: {0}")]
    PairingStore(#[from] PairingStoreError),
    #[error("I/O failed: {0}")]
    Io(#[from] io::Error),
}

struct SessionInner {
    state: SessionState,
    tcp: Option<TlsPskStream<std::net::TcpStream>>,
    udp: Option<UdpSocket>,
    udp_send: Option<DatagramCipher>,
    udp_receive: Option<DatagramCipher>,
    next_tcp_sequence: u32,
    next_udp_sequence: u32,
    pairing: Option<PairingRecord>,
    server: Option<Handshake>,
    session_salt: Option<[u8; 16]>,
    frames: FrameAssembler,
    audio: AudioFragmentReassembler,
    cursor: CursorState,
}

impl Default for SessionInner {
    fn default() -> Self {
        Self {
            state: SessionState::Disconnected,
            tcp: None,
            udp: None,
            udp_send: None,
            udp_receive: None,
            next_tcp_sequence: 0,
            next_udp_sequence: 0,
            pairing: None,
            server: None,
            session_salt: None,
            frames: FrameAssembler::default(),
            audio: AudioFragmentReassembler::default(),
            cursor: CursorState::default(),
        }
    }
}

/// Thread-safe client session orchestrator. Network reads are explicit so callers can own their runtime.
#[derive(Clone)]
pub struct ClientSession {
    config: SessionConfig,
    store: PairingStore,
    inner: Arc<Mutex<SessionInner>>,
}

impl ClientSession {
    pub fn new(config: SessionConfig) -> Result<Self, SessionError> {
        let store = match config.pairing_store_path.clone() {
            Some(path) => PairingStore::new(path),
            None => PairingStore::open_default()?,
        };
        Ok(Self {
            config,
            store,
            inner: Arc::new(Mutex::new(SessionInner::default())),
        })
    }

    pub fn state(&self) -> Result<SessionState, SessionError> {
        Ok(self.inner.lock().map_err(|_| SessionError::Poisoned)?.state)
    }

    pub fn pair_with_pin(&self, pin: &str) -> Result<ReadySession, SessionError> {
        let psk = PskIdentity::bootstrap(pin)?;
        self.connect_with_psk(psk, SessionState::AwaitingPairing)?;
        self.send_packet(
            PacketType::PairingRequest,
            &PairingRequest {
                name: self.config.client_name.clone(),
            }
            .encode()?,
        )?;
        let (header, payload) = self.read_tcp_packet()?;
        let pairing = match header.packet_type {
            PacketType::PairingGrant => {
                let grant = PairingGrant::decode(&payload)?;
                let record = PairingRecord {
                    id: grant.pairing_id,
                    name: grant.host_name,
                    key: grant.key.to_vec(),
                    added_at_unix_ms: current_unix_ms() as u64,
                };
                self.store.save(record.clone())?;
                record
            }
            PacketType::PairingReject => {
                return Err(SessionError::PairingRejected(
                    PairingReject::decode(&payload)?.reason,
                ));
            }
            actual => {
                return Err(SessionError::UnexpectedPacket {
                    expected: PacketType::PairingGrant,
                    actual,
                });
            }
        };
        self.begin_handshake(pairing)
    }

    pub fn reconnect(&self, pairing_id: &str) -> Result<ReadySession, SessionError> {
        let pairing = self
            .store
            .load(pairing_id)?
            .ok_or_else(|| SessionError::PairingNotFound(pairing_id.to_owned()))?;
        let psk = PskIdentity::pairing(&pairing.id, &pairing.key)?;
        self.connect_with_psk(psk, SessionState::AwaitingHandshakeAck)?;
        self.begin_handshake(pairing)
    }

    pub fn send_input(&self, event: InputEvent) -> Result<(), SessionError> {
        self.send_ready_packet(PacketType::InputEvent, &event.encode()?)
    }

    pub fn send_control(&self, control: ControlMessage) -> Result<(), SessionError> {
        self.send_ready_packet(PacketType::Control, &control.encode()?)
    }

    pub fn send_udp(&self, packet_type: PacketType, payload: &[u8]) -> Result<(), SessionError> {
        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
        if inner.state != SessionState::Ready {
            return Err(SessionError::NotReady);
        }
        inner.next_udp_sequence = inner.next_udp_sequence.wrapping_add(1);
        let header = PacketHeader::new(packet_type, inner.next_udp_sequence, current_unix_ms(), 0);
        let datagram = inner
            .udp_send
            .as_mut()
            .ok_or(SessionError::NotReady)?
            .seal_datagram(&header, payload)?;
        inner
            .udp
            .as_ref()
            .ok_or(SessionError::NotReady)?
            .send(&datagram)?;
        Ok(())
    }

    pub fn send_bitrate_adjust(&self, target_bitrate: i32) -> Result<(), SessionError> {
        self.send_control(ControlMessage::BitrateAdjust(BitrateAdjust {
            target_bitrate,
        }))
    }

    pub fn evaluate_abr(
        &self,
        abr: &mut crate::AbrController,
        now: std::time::Instant,
    ) -> Result<Option<i32>, SessionError> {
        let loss_ratio = self
            .inner
            .lock()
            .map_err(|_| SessionError::Poisoned)?
            .frames
            .loss_ratio(now);
        let target = abr.evaluate(loss_ratio, now);
        if let Some(target) = target {
            self.send_bitrate_adjust(target)?;
        }
        Ok(target)
    }

    pub fn send_clipboard_text(&self, text: String) -> Result<(), SessionError> {
        self.send_control(ControlMessage::ClipboardSyncUpdate(ClipboardSyncUpdate {
            request_id: 0,
            direction: ClipboardSyncDirection::ClientToHost,
            origin: ClipboardSyncOrigin::LocalPasteboard,
            text,
        }))
    }

    pub fn apply_remote_clipboard<C: PlatformClipboard>(
        &self,
        clipboard: &C,
        text: &str,
    ) -> Result<u64, SessionError> {
        clipboard.set_text(text).map_err(|error| {
            SessionError::Io(io::Error::new(io::ErrorKind::Other, error.to_string()))
        })
    }

    pub fn receive_tcp_event(&self) -> Result<SessionEvent, SessionError> {
        let (header, payload) = self.read_tcp_packet()?;
        self.handle_packet(header, payload, false)
    }

    /// Starts a background TCP control loop and exposes decoded session events.
    pub fn spawn_tcp_runtime(&self) -> Result<SessionRuntime, SessionError> {
        if self.state()? != SessionState::Ready {
            return Err(SessionError::NotReady);
        }
        {
            let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
            inner
                .tcp
                .as_mut()
                .ok_or(SessionError::NotReady)?
                .ssl_stream_mut()
                .get_ref()
                .set_read_timeout(Some(TCP_RUNTIME_READ_SLICE))?;
        }
        let session = self.clone();
        let (stop_tx, stop_rx) = mpsc::channel();
        let (event_tx, event_rx) = mpsc::channel();
        let worker = thread::spawn(move || loop {
            if stop_rx.try_recv().is_ok() {
                break;
            }
            match session.receive_tcp_event() {
                Ok(SessionEvent::Ignored) => {}
                Ok(event) => {
                    if event_tx.send(Ok(event)).is_err() {
                        break;
                    }
                }
                Err(SessionError::Tls(TlsPskError::Io(error)))
                    if matches!(
                        error.kind(),
                        io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock
                    ) => {}
                Err(error) => {
                    let _ = event_tx.send(Err(error));
                    break;
                }
            }
        });
        Ok(SessionRuntime {
            events: event_rx,
            stop: Some(stop_tx),
            worker: Some(worker),
        })
    }

    pub fn receive_udp_event(&self) -> Result<SessionEvent, SessionError> {
        let mut datagram = [0_u8; 65_536];
        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
        if inner.state != SessionState::Ready {
            return Err(SessionError::NotReady);
        }
        let received = inner
            .udp
            .as_ref()
            .ok_or(SessionError::NotReady)?
            .recv(&mut datagram)?;
        let (header, payload) = inner
            .udp_receive
            .as_mut()
            .ok_or(SessionError::NotReady)?
            .open_datagram(&datagram[..received])?;
        drop(inner);
        self.handle_packet(header, payload, true)
    }

    pub fn disconnect(&self) -> Result<(), SessionError> {
        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
        inner.state = SessionState::Disconnected;
        inner.tcp = None;
        inner.udp = None;
        inner.udp_send = None;
        inner.udp_receive = None;
        inner.frames.clear();
        inner.audio.clear();
        Ok(())
    }

    fn connect_with_psk(
        &self,
        psk: PskIdentity,
        next_state: SessionState,
    ) -> Result<(), SessionError> {
        {
            let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
            inner.state = SessionState::Connecting;
        }
        let address = resolve_one((&*self.config.host, self.config.tcp_port))?;
        let tcp = std::net::TcpStream::connect_timeout(&address, self.config.connect_timeout)?;
        tcp.set_read_timeout(Some(self.config.connect_timeout))?;
        tcp.set_write_timeout(Some(self.config.connect_timeout))?;
        tcp.set_nodelay(true)?;
        let stream = TlsPskClient::new(psk)?.connect_stream(tcp)?;
        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
        inner.tcp = Some(stream);
        inner.state = next_state;
        Ok(())
    }

    fn begin_handshake(&self, pairing: PairingRecord) -> Result<ReadySession, SessionError> {
        let mut salt = [0_u8; 16];
        OsRng.fill_bytes(&mut salt);
        let handshake = Handshake {
            name: self.config.client_name.clone(),
            width: 0,
            height: 0,
            scale: 1.0,
            version: PROTOCOL_VERSION,
            capabilities: self.config.capabilities,
            pairing_id: pairing.id.clone(),
            session_salt: salt,
        };
        {
            let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
            inner.pairing = Some(pairing.clone());
            inner.session_salt = Some(salt);
            inner.state = SessionState::AwaitingHandshakeAck;
            if let Some(tcp) = inner.tcp.as_mut() {
                tcp.ssl_stream_mut()
                    .get_ref()
                    .set_read_timeout(Some(self.config.handshake_ack_timeout))?;
            }
        }
        self.send_packet(PacketType::Handshake, &handshake.encode()?)?;
        let (header, payload) = match self.read_tcp_packet() {
            Ok(packet) => packet,
            Err(SessionError::Tls(TlsPskError::Io(error)))
                if matches!(
                    error.kind(),
                    io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock
                ) =>
            {
                return Err(SessionError::HandshakeAckTimeout);
            }
            Err(error) => return Err(error),
        };
        if header.packet_type != PacketType::HandshakeAck {
            return Err(SessionError::UnexpectedPacket {
                expected: PacketType::HandshakeAck,
                actual: header.packet_type,
            });
        }
        let server = Handshake::decode(&payload)?;
        let key = pairing.key_array()?;
        let udp_send = DatagramCipher::derive(&key, &salt, Direction::ClientToHost)?;
        let udp_receive = DatagramCipher::derive(&key, &salt, Direction::HostToClient)?;
        let udp_address = resolve_one((&*self.config.host, self.config.udp_port))?;
        let udp = UdpSocket::bind(if udp_address.is_ipv6() {
            "[::]:0"
        } else {
            "0.0.0.0:0"
        })?;
        udp.connect(udp_address)?;
        udp.set_read_timeout(Some(HEARTBEAT_INTERVAL * 3))?;
        udp.send(&[0xff])?;
        if let Some(tcp) = self
            .inner
            .lock()
            .map_err(|_| SessionError::Poisoned)?
            .tcp
            .as_mut()
        {
            tcp.ssl_stream_mut().get_ref().set_read_timeout(None)?;
        }
        let ready = ReadySession {
            pairing: pairing.clone(),
            server: server.clone(),
            session_salt: salt,
        };
        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
        inner.udp = Some(udp);
        inner.udp_send = Some(udp_send);
        inner.udp_receive = Some(udp_receive);
        inner.server = Some(server);
        inner.state = SessionState::Ready;
        Ok(ready)
    }

    fn send_ready_packet(
        &self,
        packet_type: PacketType,
        payload: &[u8],
    ) -> Result<(), SessionError> {
        if self.state()? != SessionState::Ready {
            return Err(SessionError::NotReady);
        }
        self.send_packet(packet_type, payload)
    }

    fn send_packet(&self, packet_type: PacketType, payload: &[u8]) -> Result<(), SessionError> {
        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
        inner.next_tcp_sequence = inner.next_tcp_sequence.wrapping_add(1);
        let header = PacketHeader::new(packet_type, inner.next_tcp_sequence, current_unix_ms(), 0);
        let mut packet = header.encode()?;
        packet.extend_from_slice(payload);
        inner
            .tcp
            .as_mut()
            .ok_or(SessionError::NotReady)?
            .write_frame(&packet)?;
        Ok(())
    }

    fn read_tcp_packet(&self) -> Result<(PacketHeader, Vec<u8>), SessionError> {
        let frame = self
            .inner
            .lock()
            .map_err(|_| SessionError::Poisoned)?
            .tcp
            .as_mut()
            .ok_or(SessionError::NotReady)?
            .read_frame()?;
        if frame.len() < PacketHeader::SIZE {
            return Err(SessionError::Io(io::Error::new(
                io::ErrorKind::InvalidData,
                "TCP packet is shorter than the v3 header",
            )));
        }
        Ok((
            PacketHeader::decode(&frame[..PacketHeader::SIZE])?,
            frame[PacketHeader::SIZE..].to_vec(),
        ))
    }

    fn handle_packet(
        &self,
        header: PacketHeader,
        payload: Vec<u8>,
        from_udp: bool,
    ) -> Result<SessionEvent, SessionError> {
        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
        if inner.state != SessionState::Ready {
            return Err(SessionError::NotReady);
        }
        match header.packet_type {
            PacketType::FrameHeader if from_udp => Ok(inner
                .frames
                .push_header(
                    FrameHeader::decode(&payload)?,
                    header.timestamp_ms,
                    std::time::Instant::now(),
                )?
                .map_or(SessionEvent::Ignored, SessionEvent::Frame)),
            PacketType::FrameChunk if from_udp => Ok(inner
                .frames
                .push_chunk(FrameChunk::decode(&payload)?, std::time::Instant::now())?
                .map_or(SessionEvent::Ignored, SessionEvent::Frame)),
            PacketType::AudioFrame if from_udp => Ok(inner
                .audio
                .push(AudioFragment::decode(&payload)?)
                .map_or(SessionEvent::Ignored, SessionEvent::Audio)),
            PacketType::CursorUpdate if from_udp => {
                inner.cursor.update(CursorUpdate::decode(&payload)?);
                Ok(SessionEvent::Cursor(inner.cursor))
            }
            PacketType::Ping => {
                drop(inner);
                self.send_control(ControlMessage::Pong)?;
                Ok(SessionEvent::Ping)
            }
            PacketType::Control => match ControlMessage::decode(&payload)? {
                ControlMessage::Ping => {
                    drop(inner);
                    self.send_control(ControlMessage::Pong)?;
                    Ok(SessionEvent::Ping)
                }
                ControlMessage::ClipboardSyncUpdate(update) => {
                    Ok(SessionEvent::Clipboard(update.text))
                }
                _ => Ok(SessionEvent::Ignored),
            },
            _ => Ok(SessionEvent::Ignored),
        }
    }
}

pub struct SessionRuntime {
    events: mpsc::Receiver<Result<SessionEvent, SessionError>>,
    stop: Option<mpsc::Sender<()>>,
    worker: Option<thread::JoinHandle<()>>,
}

impl SessionRuntime {
    pub fn events(&self) -> &mpsc::Receiver<Result<SessionEvent, SessionError>> {
        &self.events
    }

    pub fn stop(&mut self) {
        if let Some(stop) = self.stop.take() {
            let _ = stop.send(());
        }
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
    }
}

impl Drop for SessionRuntime {
    fn drop(&mut self) {
        self.stop();
    }
}

fn resolve_one(address: impl ToSocketAddrs) -> Result<SocketAddr, SessionError> {
    address
        .to_socket_addrs()?
        .next()
        .ok_or(SessionError::NoAddress)
}

fn current_unix_ms() -> u32 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u32
}

impl From<crate::MediaAssemblyError> for SessionError {
    fn from(error: crate::MediaAssemblyError) -> Self {
        SessionError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            error.to_string(),
        ))
    }
}

use std::{
    collections::{BTreeMap, HashMap, VecDeque},
    time::{Duration, Instant},
};

use erd_proto::{CursorUpdate, FrameChunk, FrameHeader, MAX_CHUNKS_PER_FRAME, MAX_FRAME_BYTES};
use thiserror::Error;

const MAX_ORPHAN_FRAMES: usize = 16;
const ASSEMBLY_TIMEOUT: Duration = Duration::from_secs(1);

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssembledFrame {
    pub header: FrameHeader,
    pub data: Vec<u8>,
    pub timestamp_ms: u32,
}

#[derive(Debug)]
struct FrameAssembly {
    header: FrameHeader,
    chunks: BTreeMap<u16, Vec<u8>>,
    started: Instant,
    timestamp_ms: u32,
}

#[derive(Debug, Error, PartialEq, Eq)]
pub enum MediaAssemblyError {
    #[error("frame header exceeds protocol caps")]
    InvalidHeader,
    #[error("frame chunk index is outside the declared frame")]
    InvalidChunkIndex,
    #[error("assembled frame size differs from its header")]
    SizeMismatch,
}

#[derive(Debug, Default)]
pub struct FrameAssembler {
    frames: HashMap<u32, FrameAssembly>,
    orphans: HashMap<u32, BTreeMap<u16, Vec<u8>>>,
    expected_frame_id: Option<u32>,
    recent_loss: VecDeque<(Instant, u64, u64)>,
    completed_frames: u64,
}

impl FrameAssembler {
    pub fn push_header(
        &mut self,
        header: FrameHeader,
        timestamp_ms: u32,
        now: Instant,
    ) -> Result<Option<AssembledFrame>, MediaAssemblyError> {
        if header.total_chunks == 0
            || header.total_chunks > MAX_CHUNKS_PER_FRAME
            || header.total_size == 0
            || header.total_size > MAX_FRAME_BYTES
        {
            return Err(MediaAssemblyError::InvalidHeader);
        }
        self.expire(now);
        self.track_loss(header.frame_id, now);
        if header.is_key_frame {
            self.frames.retain(|frame_id, assembly| {
                *frame_id >= header.frame_id || Self::complete(assembly)
            });
        }
        let chunks = self.orphans.remove(&header.frame_id).unwrap_or_default();
        let frame_id = header.frame_id;
        let assembly = FrameAssembly {
            header,
            chunks,
            started: now,
            timestamp_ms,
        };
        self.frames.insert(frame_id, assembly);
        self.finish_if_complete(frame_id)
    }

    pub fn push_chunk(
        &mut self,
        chunk: FrameChunk,
        now: Instant,
    ) -> Result<Option<AssembledFrame>, MediaAssemblyError> {
        self.expire(now);
        if let Some(assembly) = self.frames.get_mut(&chunk.frame_id) {
            if chunk.chunk_index >= assembly.header.total_chunks {
                return Err(MediaAssemblyError::InvalidChunkIndex);
            }
            assembly
                .chunks
                .entry(chunk.chunk_index)
                .or_insert(chunk.data);
            return self.finish_if_complete(chunk.frame_id);
        }

        if self.orphans.len() >= MAX_ORPHAN_FRAMES && !self.orphans.contains_key(&chunk.frame_id) {
            return Ok(None);
        }
        let orphans = self.orphans.entry(chunk.frame_id).or_default();
        if orphans.len() >= MAX_CHUNKS_PER_FRAME as usize {
            self.orphans.remove(&chunk.frame_id);
            return Ok(None);
        }
        orphans.entry(chunk.chunk_index).or_insert(chunk.data);
        Ok(None)
    }

    pub fn loss_ratio(&mut self, now: Instant) -> f64 {
        self.trim_loss(now);
        let (lost, total) = self.recent_loss.iter().fold(
            (0_u64, 0_u64),
            |(lost, total), (_, entry_lost, entry_total)| (lost + entry_lost, total + entry_total),
        );
        if total == 0 {
            0.0
        } else {
            lost as f64 / total as f64
        }
    }

    pub fn completed_frames(&self) -> u64 {
        self.completed_frames
    }

    pub fn clear(&mut self) {
        self.frames.clear();
        self.orphans.clear();
        self.expected_frame_id = None;
        self.recent_loss.clear();
        self.completed_frames = 0;
    }

    fn finish_if_complete(
        &mut self,
        frame_id: u32,
    ) -> Result<Option<AssembledFrame>, MediaAssemblyError> {
        let Some(assembly) = self.frames.get(&frame_id) else {
            return Ok(None);
        };
        if !Self::complete(assembly) {
            return Ok(None);
        }
        let assembly = self.frames.remove(&frame_id).expect("frame existed above");
        let mut data = Vec::with_capacity(assembly.header.total_size as usize);
        for index in 0..assembly.header.total_chunks {
            data.extend_from_slice(
                assembly
                    .chunks
                    .get(&index)
                    .ok_or(MediaAssemblyError::SizeMismatch)?,
            );
        }
        if data.len() != assembly.header.total_size as usize {
            return Err(MediaAssemblyError::SizeMismatch);
        }
        self.completed_frames += 1;
        Ok(Some(AssembledFrame {
            header: assembly.header,
            data,
            timestamp_ms: assembly.timestamp_ms,
        }))
    }

    fn complete(assembly: &FrameAssembly) -> bool {
        assembly.chunks.len() == assembly.header.total_chunks as usize
    }

    fn expire(&mut self, now: Instant) {
        self.frames.retain(|_, assembly| {
            now.saturating_duration_since(assembly.started) < ASSEMBLY_TIMEOUT
        });
    }

    fn track_loss(&mut self, frame_id: u32, now: Instant) {
        let lost = self
            .expected_frame_id
            .map_or(0, |expected| frame_id.saturating_sub(expected) as u64);
        self.recent_loss.push_back((now, lost, lost + 1));
        self.expected_frame_id = Some(
            self.expected_frame_id
                .map_or(frame_id.wrapping_add(1), |expected| {
                    expected.max(frame_id.wrapping_add(1))
                }),
        );
        self.trim_loss(now);
    }

    fn trim_loss(&mut self, now: Instant) {
        while self.recent_loss.front().is_some_and(|(timestamp, _, _)| {
            now.saturating_duration_since(*timestamp) > Duration::from_secs(5)
        }) {
            self.recent_loss.pop_front();
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct CursorState {
    pub x: f32,
    pub y: f32,
    pub cursor_type: u8,
}

impl Default for CursorState {
    fn default() -> Self {
        Self {
            x: -1.0,
            y: -1.0,
